-- Assertion-level replay of meeting-identity-transcript-access with isolated Auth IDs.
begin;
create extension if not exists pgtap with schema extensions;
set local search_path = public, extensions;
select plan(16);
select set_config('request.jwt.claims','{}',true);
insert into auth.users(id) values ('9c7302b2-0000-4000-8000-000000008701'), ('9c7302b2-0000-4000-8000-000000008702');
insert into public.users(id) values ('9c7302b2-0000-4000-8000-000000008701'), ('9c7302b2-0000-4000-8000-000000008702') on conflict do nothing;
insert into public.workspaces(id, name, personal, creator_id) values ('9c7302b2-0000-4000-8000-000000008711', 'Synthetic meeting boundary', false, '9c7302b2-0000-4000-8000-000000008701');
insert into public.workspace_members(ws_id,user_id,type) values ('9c7302b2-0000-4000-8000-000000008711','9c7302b2-0000-4000-8000-000000008701','MEMBER'), ('9c7302b2-0000-4000-8000-000000008711','9c7302b2-0000-4000-8000-000000008702','MEMBER') on conflict do nothing;
insert into public.workspace_meetings(id,ws_id,creator_id,name,time) values ('9c7302b2-0000-4000-8000-000000008721','9c7302b2-0000-4000-8000-000000008711','9c7302b2-0000-4000-8000-000000008701','Synthetic meeting',now());
insert into public.meet_ai_sessions(id,meeting_id,user_id) values ('9c7302b2-0000-4000-8000-000000008731','9c7302b2-0000-4000-8000-000000008721','9c7302b2-0000-4000-8000-000000008701');
insert into public.meet_ai_chunks(id,session_id,sequence,start_seconds,duration_seconds,transcript) values ('9c7302b2-0000-4000-8000-000000008741','9c7302b2-0000-4000-8000-000000008731',0,0,10,'Synthetic transcript');
select ok(not has_table_privilege('anon','public.meet_ai_sessions','SELECT'),'anonymous session reads denied');
select ok(not has_table_privilege('anon','public.meet_ai_chunks','SELECT'),'anonymous chunk reads denied');
select ok(not has_table_privilege('authenticated','public.meet_ai_sessions','SELECT'),'direct session reads require the application gate');
select ok(not has_table_privilege('authenticated','public.meet_ai_chunks','SELECT'),'direct chunk reads require the application gate');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"9c7302b2-0000-4000-8000-000000008702","role":"authenticated","aal":"aal2"}',true);
select ok(public.is_org_member(auth.uid(),'9c7302b2-0000-4000-8000-000000008711'),'fixture actor is a workspace member');
select is((select count(*) from public.workspace_meetings where id='9c7302b2-0000-4000-8000-000000008721'),1::bigint,'fixture actor can see the meeting');
select set_config('request.jwt.claims','{"sub":"9c7302b2-0000-4000-8000-000000008701","role":"authenticated","aal":"aal2"}',true);
select throws_ok($$update public.workspace_meetings set creator_id='9c7302b2-0000-4000-8000-000000008702' where id='9c7302b2-0000-4000-8000-000000008721'$$,'42501','Meeting creator is immutable','creator cannot replace the host');
select is((select creator_id from public.workspace_meetings where id='9c7302b2-0000-4000-8000-000000008721'),'9c7302b2-0000-4000-8000-000000008701'::uuid,'attempted host replacement changes no row');
select throws_ok($$update public.workspace_meetings set creator_id=null where id='9c7302b2-0000-4000-8000-000000008721'$$,'42501','Meeting creator is immutable','creator cannot clear the host');
select lives_ok($$update public.workspace_meetings set name='Renamed synthetic meeting',creator_id='9c7302b2-0000-4000-8000-000000008701' where id='9c7302b2-0000-4000-8000-000000008721'$$,'creator updates and unchanged creator survive');
select throws_ok($$select * from public.meet_ai_sessions$$,'42501',null,'member cannot bypass room sharing for sessions');
select throws_ok($$select * from public.meet_ai_chunks$$,'42501',null,'member cannot bypass room sharing for chunks');
reset role;
select set_config('request.jwt.claims','{}',true);
set local role service_role;
select is((select count(*) from public.meet_ai_sessions where id='9c7302b2-0000-4000-8000-000000008731'),1::bigint,'application can read sessions after its room gate');
select is((select count(*) from public.meet_ai_chunks where id='9c7302b2-0000-4000-8000-000000008741'),1::bigint,'application can read chunks after its room gate');
reset role;
select is((select creator_id from public.workspace_meetings where id='9c7302b2-0000-4000-8000-000000008721'),'9c7302b2-0000-4000-8000-000000008701'::uuid,'host remains unchanged');
select is((select name from public.workspace_meetings where id='9c7302b2-0000-4000-8000-000000008721'),'Renamed synthetic meeting','ordinary edits persist');
select * from finish();
rollback;
